),nullable(post_string('oxygen_saturation')),nullable(post_string('doctor_notes')),$complete?'Completed':'Draft']);$consultationId=(int)$pdo->lastInsertId();}else{$consultationId=(int)$consultation['consultation_id'];$pdo->prepare('UPDATE consultations SET chief_complaint=?,symptoms=?,diagnosis=?,blood_pressure=?,temperature=?,weight=?,pulse_rate=?,oxygen_saturation=?,doctor_notes=?,consultation_status=? WHERE consultation_id=?')->execute([nullable(post_string('chief_complaint')),nullable(post_string('symptoms')),nullable(post_string('diagnosis')),nullable(post_string('blood_pressure')),nullable(post_string('temperature')),nullable(post_string('weight')),nullable(post_string('pulse_rate')),nullable(post_string('oxygen_saturation')),nullable(post_string('doctor_notes')),$complete?'Completed':'Draft',$consultationId]);}
